clean = {$trim%($sub%($trim%$0, '(?i)^(?:applicability|decision[_ ]boundary|not met|met|uncertain)\s*:\s*', ''))};
texts = $clean ↦ $parts;

$render%{
  applicability=[$texts.0],
  decision_boundary=[
    "Decision boundary:\n" ++ $texts.1,
    "MET:\n" ++ $texts.2,
    "NOT MET:\n" ++ $texts.3,
    "UNCERTAIN:\n" ++ $texts.4
  ]
}
